import math
import re
from abc import ABC, abstractmethod
from time import sleep

from .telnet import TelnetOpticalSwitch


class Leoni(TelnetOpticalSwitch, ABC):
    """
    | Base class of Leoni optical switches
    | Kwargs available in the interface:

    :param str model: name of the optical switch model
    :param str addr: IP address of the optical switch
    :param int, optional port: Port of the optical switch *(defaults to 10001)*
    :param int, optional timeout: Timeout for the optical switch *(defaults to 10)*
    """

    cr_lf = "\r\n"

    def __init__(self, addr, port=10001, timeout=10):
        super().__init__(addr, port, timeout)

    def get_optical_switch_channels(self):
        """
        Get information about optical switch channels

        :raises Timeout(OpticalSwitchConnectionError): Request didn't succeed in the specified timeout.
        :raises OpticalSwitchConnectionError: Telnet connection closed unexpectedly.
        :return: Dictionary with input channel as key and output channel as value
        """
        cmd = self._build_telnet_get_command()
        response = self._send_telnet_command_and_get_response(cmd)
        parsed_response = self._parse_get_response(response)
        return parsed_response

    def set_optical_switch_channels(self, new_settings):
        """
        Set optical switch channels settings

        :param dict new_settings: dictionary with module as key and channel as value
        :raises Timeout(OpticalSwitchConnectionError): Request didn't succeed in the specified timeout.
        :raises OpticalSwitchConnectionError: Telnet connection closed unexpectedly.
        :raises InvalidInput(OpticalSwitchError): Given module or channel is out of range.
        """
        current_settings = self.get_optical_switch_channels()
        cmd = self._build_telnet_set_command(current_settings, new_settings)
        self.telnet_client.write_cmd(cmd)
        self._check_if_settings_changed(new_settings)

    def remove_all_connections(self):
        """
        Close all connections on the optical switch

        :raises OpticalSwitchConnectionError: Telnet connection closed unexpectedly.
        """
        cmd = self._build_telnet_remove_all_command()
        self.telnet_client.write_cmd(cmd)

    def _build_telnet_set_command(self, current_settings, new_settings):
        self._check_if_modules_and_channels_in_range(new_settings)
        current_settings.update(new_settings)
        bin_settings = self._convert_settings_dict_to_bin(current_settings)
        hex_settings = self._convert_bin_to_hex(bin_settings)
        set_cmd = self.set_prefix + hex_settings + self.cr_lf
        return set_cmd.encode(self._encoding)

    def _send_telnet_command_and_get_response(self, cmd) -> str:
        self.telnet_client.write_cmd(cmd)
        response = self.telnet_client.collect_output()
        return response

    def _parse_get_response(self, resp):
        hex_settings = self._get_hex_match_from_resp(resp)
        bin_settings_str = self._convert_settings_hex_to_bin(hex_settings)
        settings = self._convert_settings_bin_str_to_dict(bin_settings_str)
        return settings

    def _get_hex_match_from_resp(self, resp):
        expected_regex = re.compile(r"([\dA-Fa-f]{{1,{}}})".format(self.max_hex_length))
        match = expected_regex.search(resp)
        return match.group(1)

    def _convert_settings_hex_to_bin(self, settings_hex):
        return bin(int(settings_hex, 16))[2:].zfill(
            self.bits_per_switch * self.module_amount
        )

    def _convert_settings_bin_str_to_dict(self, settings_bin):
        bits_per_switch = self._convert_settings_bin_str_to_list(settings_bin)
        return self._convert_settings_bin_list_to_dict(bits_per_switch)

    def _convert_settings_bin_str_to_list(self, settings_bin):
        bits_per_switch = []
        for i in range(
            0, self.module_amount * self.bits_per_switch, self.bits_per_switch
        ):
            bits_per_switch.append(settings_bin[i: i + self.bits_per_switch])
        return bits_per_switch

    def _convert_settings_bin_list_to_dict(self, bits_per_switch):
        settings = {}
        module_number = self.module_amount
        for bits in bits_per_switch:
            channel = int(bits, 2) + 1
            settings[module_number] = channel
            module_number -= 1
        return settings

    def _convert_settings_dict_to_bin(self, settings):
        bin_settings = ""
        for module in range(self.module_amount, 0, -1):
            channel_bin = "{0:b}".format(settings[module] - 1)
            channel_bin_settings = channel_bin.zfill(self.bits_per_switch)
            bin_settings += channel_bin_settings
        return bin_settings

    def _convert_bin_to_hex(self, bin_settings):
        return "{0:x}".format(int(bin_settings, 2)).zfill(
            self.hex_length_for_set_command
        )

    @property
    @abstractmethod
    def check_code(self):
        pass

    @property
    @abstractmethod
    def set_prefix(self):
        pass

    @property
    @abstractmethod
    def hex_length_for_set_command(self):
        # ensures 'set_channels' command sends properly formatted values, e.g. 0e4 instead of just e4
        pass

    @property
    def max_hex_length(self):
        return int(math.ceil((self.module_amount * self.bits_per_switch) / 16.0) * 4)

    @property
    def bits_per_switch(self):
        return (self.channel_amount - 1).bit_length()

    def _build_telnet_get_command(self):
        return self.check_code.encode(self._encoding)

    def _build_telnet_remove_all_command(self):
        remove_command = self.set_prefix + "00\r\n"
        return remove_command.encode(self._encoding)


class Leoni_mol_6x_2x6(Leoni):
    def __init__(self, addr, **kwargs):
        super().__init__(addr, **kwargs)

    @property
    def check_code(self):
        return "gr?\r\n"

    @property
    def set_prefix(self):
        return "gr0"

    @property
    def module_amount(self):
        return 6

    @property
    def channel_amount(self):
        return 4

    @property
    def hex_length_for_set_command(self):
        return 3

    def _send_telnet_command_and_get_response(self, cmd) -> str:
        self.telnet_client.write_cmd(cmd)
        response = self.telnet_client.collect_output_until(self.cr_lf.encode(), self._timeout)
        return response


class Leoni_mol_2x_1x8(Leoni):
    def __init__(self, addr, **kwargs):
        super().__init__(addr, **kwargs)

    @property
    def check_code(self):
        return "ch?\r\n"

    @property
    def set_prefix(self):
        return "ch"

    @property
    def module_amount(self):
        return 1

    @property
    def channel_amount(self):
        return 8

    @property
    def hex_length_for_set_command(self):
        return 2

    def _parse_get_response(self, resp):
        return {1: int(resp.split("\r\n")[0])}

    def _build_telnet_set_command(self, current_settings, new_settings):
        self._check_if_modules_and_channels_in_range(new_settings)
        set_cmd = "".join(f"{self.set_prefix}{v}\r\n" for _, v in new_settings.items())
        return set_cmd.encode(self._encoding)


class Leoni_mol_12x_2x12(Leoni):
    def __init__(self, addr, **kwargs):
        super().__init__(addr, **kwargs)

    @property
    def check_code(self):
        return "set?\r\n"

    @property
    def set_prefix(self):
        return "set"

    @property
    def module_amount(self):
        return 2

    @property
    def channel_amount(self):
        return 12

    @property
    def hex_length_for_set_command(self):
        return 3

    def _build_telnet_set_command(self, current_settings, new_settings):
        self._check_if_modules_and_channels_in_range(new_settings)
        updated_settings = self._drop_not_changed_values(current_settings, new_settings)
        set_cmd = "".join(
            [f"{self.set_prefix}{k}{v}\r\n" for k, v in updated_settings.items()]
        )
        return set_cmd.encode(self._encoding)

    def _parse_get_response(self, resp):
        settings_list = self._get_list_of_settings(resp)
        return self._parse_settings_to_dict(settings_list)

    @staticmethod
    def _get_list_of_settings(resp):
        return [i[11:].strip() for i in resp.split("\r\n")[:-1] if i]

    @staticmethod
    def _parse_settings_to_dict(settings_list):
        return {int(i[0]): int(i[1:]) for i in settings_list}

    def _drop_not_changed_values(self, current_settings, new_settings):
        result = {}
        for k, v in new_settings.items():
            if k in current_settings and v == current_settings[k]:
                continue
            result[k] = v
        return result


