class Leoni_mol_2x_2x12(Leoni):
    def __init__(self, addr, **kwargs):
        super().__init__(addr, **kwargs)

    @property
    def check_code(self):
        return "set?\r\n"

    @property
    def set_prefix(self):
        return "set"

    @property
    def module_amount(self):
        return 2

    @property
    def channel_amount(self):
        return 12

    @property
    def hex_length_for_set_command(self):
        return 3

    def _build_telnet_set_command(self, current_settings, new_settings):
        sleep(0.1)
        self._check_if_modules_and_channels_in_range(new_settings)
        updated_settings = self._drop_not_changed_values(current_settings, new_settings)
        set_cmd = "".join(
            [f"{self.set_prefix}{k}{v}\r\n" for k, v in updated_settings.items()]
        )
        return set_cmd.encode(self._encoding)

    def _send_telnet_command_and_get_response(self, cmd) -> str:
        self.telnet_client.write_cmd(cmd)
        sleep(0.1)
        response = self.telnet_client.collect_output()
        return response

    def _parse_get_response(self, resp):
        if "blind" in resp:
            return {}
        settings_list = self._get_list_of_settings(resp)
        return self._parse_settings_to_dict(settings_list)

    @staticmethod
    def _get_list_of_settings(resp):
        return [re.match(r".* (\d+)", i).group(1) for i in resp.strip().split("\r\n")]

    @staticmethod
    def _parse_settings_to_dict(settings_list):
        return {int(i[0]): int(i[1:]) for i in settings_list if i}

    @staticmethod
    def _drop_not_changed_values(current_settings, new_settings):
        return {
            k: v
            for k, v in new_settings.items()
            if k not in current_settings or current_settings[k] != v
        }
